import sys, os; sys.path.insert(0, os.path.dirname(os.path.dirname(__file__)))
from dsl import *
U("s1-u15")

L(1, "No café", "Pedir, pagar e agradecer numa conversa completa.",
  ["Pedir bebidas e comida simples", "Pagar e agradecer"],
  vocab=[V("v-thee","thee","chá","noun","de"), V("v-bier","bier","cerveja","noun","het",note="Um copo de cerveja: een biertje."),
         V("v-willen","willen","querer","verb",note="ik wil, jij wilt (wil je?), hij wil"), V("v-betalen","betalen","pagar","verb"),
         V("v-pinnen","pinnen","pagar com cartão","verb",note="Muito usado: Kan ik pinnen? = Posso pagar com cartão?")],
  ex=[("Ik wil graag een koffie.","Queria um café, por favor."),("Kan ik pinnen?","Posso pagar com cartão?"),("Mag ik betalen?","Posso pagar? / A conta, por favor.")],
  gram=[G("g-ik-wil-graag","Ik wil graag…","Para pedir com educação: **Ik wil graag** + produto (*ik wil graag een thee*) ou **Mag ik** + produto (*mag ik een thee?*). «Ik wil» sozinho pode soar brusco; «graag» suaviza.",
    [("Ik wil graag betalen.","Queria pagar."),("Mag ik de rekening?","Pode trazer a conta?")],
    "Equivale ao nosso «queria…» condicional de cortesia.")],
  review=["v-koffie","v-graag","v-alstublieft","v-dank-u-wel","v-kosten"],
  exs=[
    MA([("thee","chá"),("bier","cerveja"),("willen","querer"),("betalen","pagar"),("pinnen","pagar com cartão")], "No café.", ["v-thee","v-bier","v-willen","v-betalen","v-pinnen"]),
    MC("Qual é a forma mais educada de pedir?", ["*Ik wil graag een thee.","Ik wil een thee!|Sem «graag» pode soar brusco.","Thee!|Demasiado seco."], "Ik wil graag… = queria…", ["v-willen","v-graag"]),
    CJ("willen","jij","___ je koffie?", ["Wil"], "willen: jij wilt, mas na pergunta: wil je?", ["v-willen"]),
    TR("pt-nl","Posso pagar com cartão?", ["Kan ik pinnen"], "pinnen = pagar com cartão (de débito).", ["v-pinnen"]),
    TR("nl-pt","Ik wil graag betalen.", ["Queria pagar","Gostaria de pagar","A conta, por favor"], "Pedido educado.", ["v-betalen"]),
    AR("bier","a cerveja","het", "«Het bier»; um copo: een biertje.", ["v-bier"]),
    DL([("Empregado","Goedemiddag! Wat wilt u drinken?","Boa tarde! O que deseja beber?"),("Cliente","")], ["*Ik wil graag een thee, alstublieft.","Ik ben een thee.|Usa-se «willen», não «zijn».","Graag gedaan.|Isso é «de nada»."], "Ik wil graag + bebida.", ["v-willen","v-thee"]),
    LI("Kan ik pinnen?", ["Kan ik pinnen"], "Posso pagar com cartão?", "Frase essencial nos Países Baixos.", ["v-pinnen"]),
    CO("dialogue","No café", "Ober: Goedemiddag! Wat mag het zijn?\nAna: Een koffie en een appeltaart, alstublieft.\nOber: Alstublieft. Dat is zeven euro.\nAna: Kan ik pinnen?\nOber: Natuurlijk.",
       [("O que pede a Ana?", ["*Um café e uma tarte de maçã","Um chá","Uma cerveja"]),("Como paga?", ["*Com cartão","Em dinheiro","Não paga"])],
       "«Wat mag het zijn?» = o que vai ser?", ["v-pinnen","v-koffie"]),
    WO("Queria uma cerveja, por favor.", ["Ik","wil","graag","een","biertje,","alstublieft"], "Ik wil graag + produto.", ["v-willen","v-bier"]),
  ], diff=2, mins=6)

L(2, "Conhecer alguém numa festa", "Apresentar-se, perguntar e manter a conversa.",
  ["Iniciar e manter uma conversa curta"],
  vocab=[V("v-feest","feest","festa","noun","het","feesten"), V("v-gezellig","gezellig","agradável|acolhedor|animado","adjective",note="Palavra-chave da cultura neerlandesa: ambiente acolhedor e bom convívio."),
         V("v-iemand","iemand","alguém","pronoun"), V("v-samen","samen","juntos","adverb")],
  ex=[("Wat een gezellig feest!","Que festa tão agradável!"),("Ken je iemand hier?","Conheces alguém aqui?"),("We werken samen.","Trabalhamos juntos.")],
  gram=[G("g-gezellig","Gezellig","**gezellig** não tem tradução exata: descreve um ambiente acolhedor, descontraído e de bom convívio. Usa-se para festas, casas, cafés e pessoas: *Het was heel gezellig!* (Foi muito agradável!)",
    [("Een gezellig café.","Um café acolhedor."),("Het was gezellig!","Foi muito bom (estar juntos)!")])],
  review=["v-heten","v-komen-uit","v-kennen","v-leuk-je-te-ontmoeten","v-wonen"],
  exs=[
    MA([("feest","festa"),("gezellig","agradável"),("iemand","alguém"),("samen","juntos")], "Numa festa.", ["v-feest","v-gezellig","v-iemand","v-samen"]),
    EX("Het was heel gezellig!", "Foi muito acolhedor!", "No fim de um jantar com amigos, alguém diz isto. O que quer dizer?", ["*Que foi um serão muito agradável","Que a comida estava fria|Não tem a ver com a comida.","Que está cansado|Isso seria «ik ben moe»."], "gezellig = bom ambiente, bom convívio.", ["v-gezellig"]),
    TR("pt-nl","Conheces alguém aqui?", ["Ken [je|jij] iemand hier"], "kennen + iemand.", ["v-kennen","v-iemand"]),
    TR("nl-pt","We werken samen.", ["(Nós )trabalhamos juntos"], "samen = juntos.", ["v-samen"]),
    AR("feest","a festa","het", "«Het feest».", ["v-feest"]),
    DL([("Sanne","Hoi! Ik ben Sanne. Hoe ken jij Tom?","Olá! Sou a Sanne. Como conheces o Tom?"),("Pedro","")], ["*We werken samen.","Ik ben Tom.|Não responde.","Ik ken hem niet hier.|Ordem errada e não faz sentido."], "Resposta natural.", ["v-samen"]),
    FB("Wat een ___ feest!", ["gezellig","leuk"], "gezellig/leuk feest.", ["v-gezellig"], choices=["gezellig","kapot","dicht"], tr="Que festa tão agradável!"),
    LI("Ken je iemand hier?", ["Ken je iemand hier"], "Conheces alguém aqui?", "iemand ≈ «ímant».", ["v-iemand"]),
    CO("dialogue","Numa festa de anos", "Lisa: Hoi, ik ben Lisa, de zus van Tom.\nPedro: Hallo Lisa! Ik ben Pedro. Ik werk met Tom.\nLisa: O, leuk! Waar kom je vandaan?\nPedro: Uit Portugal. Ik woon nu twee jaar in Utrecht.\nLisa: Wat leuk! Spreek je al Nederlands?\nPedro: Een beetje!",
       [("Quem é a Lisa?", ["*A irmã do Tom","A namorada do Pedro","Uma colega"]),("Há quanto tempo vive o Pedro em Utrecht?", ["*Dois anos","Um ano","Dez anos"])],
       "«Spreek je al Nederlands?» = já falas neerlandês?", ["v-zus","v-wonen"]),
    SW("Apresente-se a alguém numa festa e faça-lhe uma pergunta.", ["Hoi(,) ik ben Ana(.) Hoe ken jij Tom","Hallo(,) ik heet Pedro(.) Waar kom je vandaan"],
       ["Cumprimento + nome","Uma pergunta (verbo depois da palavra interrogativa)"], 5, "Modelo: «Hoi, ik ben Ana. Hoe ken jij Tom?»", ["v-feest"]),
  ], diff=2, mins=6)

L(3, "Ao telefone", "Atender, apresentar-se e marcar um encontro simples.",
  ["Atender e fazer uma chamada curta", "Combinar dia e hora"],
  vocab=[V("v-bellen","bellen","telefonar|ligar","verb"), V("v-afspreken","afspreken","combinar","verb",note="Verbo separável: we spreken af = combinamos."),
         V("v-prima-combinado","prima","combinado|ótimo","expression"), V("v-tot-dan","tot dan","até lá|até então","expression")],
  ex=[("Met Ana.","Fala a Ana. (ao atender)"),("Zullen we morgen afspreken?","Combinamos para amanhã?"),("Om drie uur? Prima, tot dan!","Às três? Combinado, até lá!")],
  gram=[G("g-telefone","Ao telefone","Nos Países Baixos atende-se o telefone dizendo o próprio nome: **Met Ana** ou **Met Ana Silva** («fala Ana»). Para combinar: **Zullen we…?** (vamos…?). Para fechar: **Tot dan!** (até lá).",
    [("Met Tom de Vries.","Fala Tom de Vries."),("Zullen we koffie drinken?","Vamos beber um café?")],
    "Em Portugal atendemos com «Estou?» ou «Sim?»; lá é habitual dizer o nome.")],
  review=["v-morgen","v-om","v-uur","v-tijd","v-misschien"],
  exs=[
    MC("Como atende o telefone uma pessoa chamada Ana, à maneira neerlandesa?", ["*Met Ana.","Ik ben telefoon.|Não faz sentido.","Hallo, wie is daar?|Pode ouvir-se, mas o habitual é dizer o nome."], "Met + nome.", ["v-bellen"]),
    MA([("bellen","telefonar"),("afspreken","combinar"),("tot dan","até lá"),("prima","combinado")], "Ao telefone.", ["v-bellen","v-afspreken","v-tot-dan","v-prima-combinado"]),
    TR("nl-pt","Zullen we morgen afspreken?", ["Combinamos (para )amanhã","Vamos combinar (para )amanhã","Encontramo-nos amanhã"], "Zullen we…? = vamos…?", ["v-afspreken"]),
    TR("pt-nl","Até lá!", ["Tot dan"], "tot dan = até lá.", ["v-tot-dan"]),
    DL([("Eva","Heb je morgen tijd?","Tens tempo amanhã?"),("Tom","Ja, om twee uur.","Sim, às duas."),("Eva","")], ["*Prima, tot dan!","Nee, ik heb tijd.|Contraditório.","Met Eva.|Isso diz-se ao atender."], "Fechar a combinação: prima, tot dan!", ["v-tot-dan","v-prima-combinado"]),
    CJ("bellen","ik","Ik ___ je morgen.", ["bel"], "bellen → ik bel (consoante dupla fica simples).", ["v-bellen"]),
    LI("Met Pedro, goedemorgen.", ["Met Pedro(,) goedemorgen"], "Fala o Pedro, bom dia.", "Atender com o nome.", ["v-bellen"]),
    WO("Ligo-te amanhã às três.", ["Ik","bel","je","morgen","om","drie","uur"], "tempo antes de hora? morgen + om drie uur.", ["v-bellen","v-om"]),
    FB("Zullen we om vier uur ___?", ["afspreken"], "afspreken = combinar.", ["v-afspreken"], choices=["afspreken","bellen","betalen"], tr="Combinamos às quatro?"),
    CO("dialogue","Uma chamada", "Ana: Met Ana.\nSanne: Hoi Ana, met Sanne! Heb je zaterdag tijd?\nAna: Ja, hoezo?\nSanne: Zullen we samen naar de markt gaan?\nAna: Leuk! Hoe laat?\nSanne: Om tien uur bij het station.\nAna: Prima, tot dan!",
       [("O que propõe a Sanne?", ["*Irem juntas ao mercado","Irem ao cinema","Trabalharem juntas"]),("Onde se encontram?", ["*Na estação","No mercado","Em casa da Ana"]),("A que horas?", ["*Às dez","Às duas","Às oito"])],
       "«hoezo?» = porquê? (informal)", ["v-samen","v-tot-dan"]),
  ], diff=3, mins=7)

L(4, "Pedir ajuda na rua", "Com licença, onde fica…? Perceber respostas simples.",
  ["Pedir uma direção simples", "Perceber links, rechts, rechtdoor"],
  vocab=[V("v-links","links","à esquerda","adverb"), V("v-rechts","rechts","à direita","adverb"),
         V("v-rechtdoor","rechtdoor","em frente","adverb"), V("v-zoeken","zoeken","procurar","verb",note="ik zoek")],
  ex=[("Pardon, waar is het station?","Com licença, onde é a estação?"),("Rechtdoor en dan links.","Em frente e depois à esquerda."),("Ik zoek de supermarkt.","Procuro o supermercado.")],
  gram=[G("g-direcoes-basicas","Direções básicas","**links** (esquerda), **rechts** (direita), **rechtdoor** (em frente). Para pedir: **Pardon, waar is…?** ou **Ik zoek…** (procuro…). A Secção 3 aprofunda as direções.",
    [("Het is daar, rechts.","É ali, à direita.")])],
  review=["v-pardon","v-waar","v-station","v-ver","v-dichtbij"],
  exs=[
    MA([("links","esquerda"),("rechts","direita"),("rechtdoor","em frente"),("zoeken","procurar")], "Direções.", ["v-links","v-rechts","v-rechtdoor","v-zoeken"]),
    TR("pt-nl","Com licença, onde é a estação?", ["Pardon(,) waar is het station"], "Pardon + waar is…?", ["v-pardon","v-station"]),
    TR("nl-pt","Rechtdoor en dan links.", ["Em frente e depois à esquerda","Sempre em frente e depois à esquerda"], "dan = depois.", ["v-rechtdoor","v-links"]),
    CJ("zoeken","ik","Ik ___ het ziekenhuis.", ["zoek"], "zoeken → ik zoek.", ["v-zoeken"]),
    DL([("Turista","Pardon, is het station ver?","Desculpe, a estação é longe?"),("Senhora","")], ["*Nee, het is dichtbij. Hier rechtdoor.","Ja, ik ben het station.|Não faz sentido.","Ik zoek het niet.|Não responde."], "dichtbij + direção.", ["v-dichtbij","v-rechtdoor"]),
    LI("De supermarkt is hier rechts.", ["De supermarkt is hier rechts"], "O supermercado é aqui à direita.", "rechts com «ch» gutural.", ["v-rechts"]),
    FB("Ga hier ___ en dan rechts.", ["links","rechtdoor"], "Instruções de caminho.", ["v-links"], choices=["links","laat","lang"], tr="Vire aqui à esquerda e depois à direita."),
    FE(["Ik","zoekt","de","supermarkt."], 1, "zoek", "ik zoek (sem -t).", ["v-zoeken"]),
    CO("dialogue","Na rua", "Pedro: Pardon, ik zoek het museum.\nMan: Het museum? Dat is niet ver. Hier rechtdoor, en dan de tweede straat links.\nPedro: Dank u wel!\nMan: Graag gedaan.",
       [("O que procura o Pedro?", ["*O museu","A estação","O hospital"]),("Que rua deve apanhar?", ["*A segunda à esquerda","A primeira à direita","A segunda à direita"])],
       "de tweede straat links = a segunda rua à esquerda.", ["v-zoeken","v-links"]),
    WO("Procuro a estação.", ["Ik","zoek","het","station"], "zoeken + objeto.", ["v-zoeken"]),
  ], diff=3, mins=6)

L(5, "A minha primeira conversa completa", "Revisão final da Secção 1: tudo junto.",
  ["Manter uma conversa simples do início ao fim"],
  ex=[("Hoi! Ik ben Ana, ik kom uit Portugal en ik woon in Utrecht. Ik spreek een beetje Nederlands.","Olá! Sou a Ana, sou de Portugal e vivo em Utrecht. Falo um pouco de neerlandês.")],
  review=["v-heten","v-komen-uit","v-wonen","v-spreken","v-hebben","v-werken","v-geen","v-niet","v-toch","v-gezellig"],
  exs=[
    DL([("Tom","Hoi, ik ben Tom. En jij?","Olá, sou o Tom. E tu?"),("Ana","Ik ben Ana. Leuk je te ontmoeten!","Sou a Ana. Prazer!"),("Tom","Jij bent niet Nederlands, toch?","Não és neerlandesa, pois não?"),("Ana","")], ["*Nee, ik kom uit Portugal.","Ja, ik ben geen Nederlands.|Contraditório.","Nee, ik heet Portugal.|Não faz sentido."], "Confirmar com nee + origem.", ["v-toch","v-komen-uit"]),
    TR("pt-nl","Não tenho carro, vou de bicicleta.", ["Ik heb geen auto(,) ik ga met de fiets"], "geen auto; met de fiets.", ["v-geen","v-fiets"]),
    TR("nl-pt","Wat doe je in het weekend?", ["O que fazes ao fim de semana","O que fazes no fim de semana"], "het weekend = o fim de semana.", ["v-doen"]),
    MC("«Hoe lang woon je al hier?» Qual é a melhor resposta?", ["*Drie jaar.","In Utrecht.|Responde a «waar?».","Om drie uur.|Responde a «hoe laat?»."], "hoe lang = quanto tempo.", ["v-wonen"]),
    FE(["Ik","heb","dertig","jaar","en","ik","woon","in","Delft."], 1, "ben", "Idade: ik ben dertig (jaar).", ["v-hoe-oud"]),
    WO("Amanhã trabalho em casa.", ["Morgen","werk","ik","thuis"], "Inversão.", ["v-werken","v-morgen"], alt=["Ik werk morgen thuis"]),
    LI("Het was heel gezellig, tot ziens!", ["Het was heel gezellig(,) tot ziens"], "Foi muito agradável, adeus!", "Despedida calorosa.", ["v-gezellig","v-tot-ziens"]),
    CO("text","O primeiro mês da Ana", "Ana woont sinds een maand in Utrecht. Ze werkt in een ziekenhuis. Ze heeft nog geen fiets, dus ze gaat met de bus. Ze spreekt een beetje Nederlands en haar collega's zijn heel aardig. Op vrijdag drinken ze samen een biertje. Dat is altijd gezellig!",
       [("Há quanto tempo vive a Ana em Utrecht?", ["*Um mês","Um ano","Uma semana"]),("Porque vai de autocarro?", ["*Ainda não tem bicicleta","Gosta de autocarros","Vive longe"]),("O que fazem à sexta-feira?", ["*Bebem uma cerveja juntos","Vão ao mercado","Trabalham até tarde"])],
       "«nog geen fiets» = ainda não tem bicicleta.", ["v-geen","v-gezellig","v-samen"]),
    SW("Escreva uma pequena apresentação (4–5 frases): nome, origem, cidade, trabalho/estudo, línguas e uma coisa que não tem ou não faz.", ["Ik heet Ana(.) Ik kom uit Portugal(.) Ik woon in Utrecht(.) Ik werk in een ziekenhuis(.) Ik spreek Portugees en een beetje Nederlands(.) Ik heb geen auto"],
       ["Nome, origem e cidade","O que faz (werken/studeren)","Línguas com «ik spreek»","Uma negação correta (niet/geen)","Verbo em 2.º lugar em todas as frases"], 15, "Compare com o modelo e confirme cada ponto da lista.", ["v-heten","v-spreken"]),
    MA([("Gefeliciteerd!","Parabéns!"),("Geen probleem!","Não há problema!"),("Tot dan!","Até lá!"),("Kan ik pinnen?","Posso pagar com cartão?")], "Frases-chave da Secção 1.", ["v-gefeliciteerd","v-probleem","v-tot-dan","v-pinnen"]),
  ], diff=3, mins=8)

W()
